from thirdparty import RecipeBase
from thirdparty.tools.cmake import CMake, CMakeToolchain
from thirdparty.tools.files import apply_patches, copy, get, rmdir
from thirdparty.tools.microsoft import is_msvc
from thirdparty.tools.scm import Version
import os


class Recipe(RecipeBase):
    name = "libwebp"
    version = "1.6.0"
    license = "BSD-3-Clause"
    options = {
        "shared": [True, False],
        "fPIC": [True, False],
        "with_simd": [True, False],
        "near_lossless": [True, False],
        "swap_16bit_csp": [True, False],
    }
    default_options = {
        "shared": False,
        "fPIC": True,
        "with_simd": True,
        "near_lossless": True,
        "swap_16bit_csp": False,
    }

    def source(self):
        get(
            url="https://storage.googleapis.com/downloads.webmproject.org/releases/webp/libwebp-1.6.0.tar.gz",
            dest=self.source_folder,
            sha256="e4ab7009bf0629fd11982d4c2aa83964cf244cffba7347ecd39019a9e38c4564",
        )
        apply_patches(self)

    def generate(self):
        tc = CMakeToolchain(self)
        # should be an option but it doesn't work yet
        tc.variables["WEBP_ENABLE_SIMD"] = self.options.with_simd
        tc.variables["WEBP_NEAR_LOSSLESS"] = self.options.near_lossless
        tc.variables["WEBP_ENABLE_SWAP_16BIT_CSP"] = self.options.swap_16bit_csp
        # avoid finding system libs
        tc.variables["CMAKE_DISABLE_FIND_PACKAGE_GIF"] = True
        tc.variables["CMAKE_DISABLE_FIND_PACKAGE_PNG"] = True
        tc.variables["CMAKE_DISABLE_FIND_PACKAGE_TIFF"] = True
        tc.variables["CMAKE_DISABLE_FIND_PACKAGE_JPEG"] = True
        tc.variables["WEBP_BUILD_ANIM_UTILS"] = False
        tc.variables["WEBP_BUILD_CWEBP"] = False
        tc.variables["WEBP_BUILD_DWEBP"] = False
        tc.variables["WEBP_BUILD_IMG2WEBP"] = False
        tc.variables["WEBP_BUILD_GIF2WEBP"] = False
        tc.variables["WEBP_BUILD_VWEBP"] = False
        tc.variables["WEBP_BUILD_EXTRAS"] = False
        tc.variables["WEBP_BUILD_WEBPINFO"] = False
        if Version(self.version) >= "1.2.1":
            tc.variables["WEBP_BUILD_LIBWEBPMUX"] = True
        tc.variables["WEBP_BUILD_WEBPMUX"] = False
        if self.options.shared and self.is_windows:
            # Building a dll (see fix-dll-export patch)
            tc.preprocessor_definitions["WEBP_DLL"] = 1
        tc.generate()

    def build(self):
        cmake = CMake(self)
        cmake.configure()
        cmake.build()

    def package(self):
        cmake = CMake(self)
        cmake.install()
        copy(
            "COPYING",
            src=self.source_folder,
            dst=os.path.join(self.package_folder, "licenses"),
        )
        rmdir(os.path.join(self.package_folder, "lib", "pkgconfig"))
        rmdir(os.path.join(self.package_folder, "share"))

        # libwebp does not install cmake package config files; generate them so
        # downstream find_package(WebP) works when using CMAKE_PREFIX_PATH.
        webp_cmake_dir = os.path.join(
            self.package_folder, "lib", "cmake", "WebP"
        )
        os.makedirs(webp_cmake_dir, exist_ok=True)
        lib_ext = ".lib" if self.is_windows else ".a"
        _libs = ["webpdecoder", "webp", "webpdemux", "webpmux", "sharpyuv"]
        lines = [
            "# WebPConfig.cmake — generated by ThirdParty build system\n",
            'get_filename_component(_webp_root "${CMAKE_CURRENT_LIST_DIR}/../../.." ABSOLUTE)\n',
            "\n",
        ]
        for _lib in _libs:
            t = f"WebP::{_lib}"
            lines += [
                f'if(NOT TARGET {t})\n',
                f'  add_library({t} STATIC IMPORTED)\n',
                f'  set_target_properties({t} PROPERTIES\n',
                f'    IMPORTED_LOCATION "${{_webp_root}}/lib/{_lib}{lib_ext}"\n',
                f'    INTERFACE_INCLUDE_DIRECTORIES "${{_webp_root}}/include"\n',
                f'  )\n',
                f'endif()\n',
            ]
        lines += [
            "\n",
            "set(WebP_FOUND TRUE)\n",
            "set(WEBP_FOUND TRUE)\n",
            'set(WebP_INCLUDE_DIRS "${_webp_root}/include")\n',
            'set(WEBP_INCLUDE_DIRS "${_webp_root}/include")\n',
            'set(WebP_LIBRARIES "WebP::webpdecoder;WebP::webp;WebP::webpdemux;WebP::webpmux")\n',
            'set(WEBP_LIBRARIES "${WebP_LIBRARIES}")\n',
            "set(WebP_VERSION 1.6.0)\n",
            "# Alias so projects using WebP::libwebpmux (e.g. OpenImageIO) also work\n",
            'if(TARGET WebP::webpmux AND NOT TARGET WebP::libwebpmux)\n',
            '  add_library(WebP::libwebpmux INTERFACE IMPORTED)\n',
            '  set_target_properties(WebP::libwebpmux PROPERTIES\n',
            '    INTERFACE_LINK_LIBRARIES "WebP::webpmux"\n',
            '  )\n',
            'endif()\n',
        ]
        with open(os.path.join(webp_cmake_dir, "WebPConfig.cmake"), "w") as _f:
            _f.writelines(lines)

    def package_info(self):
        self.cpp_info.set_property("cmake_file_name", "WebP")
        self.cpp_info.set_property("cmake_target_name", "WebP::webp")
        self.cpp_info.set_property("cmake_package_file", "lib/cmake/WebP/WebPConfig.cmake")
